import re

_TRANSLIT = {
    'á': 'a', 'à': 'a', 'â': 'a', 'ä': 'a',
    'é': 'e', 'è': 'e', 'ê': 'e', 'ë': 'e',
    'í': 'i', 'ì': 'i', 'î': 'i', 'ï': 'i',
    'ó': 'o', 'ò': 'o', 'ô': 'o', 'ö': 'o', 'õ': 'o',
    'ú': 'u', 'ù': 'u', 'û': 'u', 'ü': 'u', 'ű': 'u',
    'ý': 'y', 'ý': 'y', 'ÿ': 'y',
    'ñ': 'n', 'ç': 'c', 'ø': 'o', 'å': 'a',
}


def slugify(s):
    s = s.lower()
    for src, dst in _TRANSLIT.items():
        s = s.replace(src, dst)
    s = re.sub(r'[^a-z0-9]+', '-', s)
    return s.strip('-')

